// taken and adapted from https://github.com/jepser/use-match-media

import { useEffect, useState, useMemo } from 'react';

import { useSafeLayoutEffect } from './useSafeLayoutEffect.js';

/**
 * `useBreakpoint` is a hook used to determine if the document matches the media
 * query string (or media query list). It will listen to the breakpoints specified
 * and will return a boolean value indicating if this media query is met or not.
 */
function useBreakpoint(
  /** Media Query you want to test, eg '(min-width: 800px)' */
  query: string,
  /** Default value (fallback value to support SSR)
   * @defaultValue false
   */
  defaultValue?: boolean,
): boolean;

/**
 * `useBreakpoint` is a hook used to determine if the document matches the media
 * query string (or media query list). It will listen to the breakpoints specified
 * and will return a boolean value indicating if this media query is met or not.
 */
function useBreakpoint(
  /** Media Queries you want to test, eg '[(min-width: 400px), (min-width: 800px)]' */
  queries: string[],
  /** Default values (fallback values to support SSR)
   * @defaultValue []
   */
  defaultValues?: boolean[],
): boolean[];
/**
 * useBreakpoint hook implementation
 */
function useBreakpoint(
  queries: string | string[],
  defaultValues?: boolean | boolean[],
): boolean | boolean[] {
  const stringQuery = Array.isArray(queries) ? queries.toString() : queries;
  const { mediaQueryLists, initialValues } = useMemo<{
    mediaQueryLists: MediaQueryList[];
    initialValues: boolean | boolean[];
  }>(() => {
    const _defaultValues = defaultValues ?? Array.isArray(queries) ? [] : false;

    if (Array.isArray(_defaultValues) && Array.isArray(queries)) {
      return {
        initialValues: _defaultValues.length
          ? _defaultValues
          : Array(queries.length).fill(false),
        mediaQueryLists: queries.map((q) => window.matchMedia(q)),
      };
    } else {
      return {
        initialValues: _defaultValues || false,
        mediaQueryLists: [window.matchMedia(queries as string)],
      };
    }
    /** Instead of checking for query, we compare the stringified version, to also reset the queries for the arrays properly. */
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stringQuery, defaultValues]);

  /* In SSR useLayoutEffect is not triggered,
   so as a fallback it is possible to provide defaults, which we return here.
   therefore we need to conditionally use the hooks in order to make SSR possible.
  */
  if (typeof window === 'undefined') {
    return initialValues;
  }

  const getValue = (): boolean[] => {
    // Return the value for the given queries
    const matchedQueries = mediaQueryLists.map((mql) => mql.matches);

    return matchedQueries;
  };

  // The early escape hatch is for SSR only and, therefore, the hook order might only differ initially.
  // eslint-disable-next-line react-hooks/rules-of-hooks
  useEffect(() => {
    setValue(getValue);
    // exclude getValue, since it gets reinitialized on render,
    // stringifying queries since the array would trigger the effect on every render and then end up in an endless loop.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stringQuery]);

  // State and setter for matched value
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const [value, setValue] = useState(getValue);

  // eslint-disable-next-line react-hooks/rules-of-hooks
  useSafeLayoutEffect(() => {
    // Event listener callback
    // Note: By defining getValue outside of useEffect we ensure that it has ...
    // ... current values of hook args (as this hook only runs on mount/dismount).
    const handler = (): void => setValue(getValue);

    // Set a listener for each media query with above handler as callback.
    mediaQueryLists.forEach((mql) => mql.addEventListener('change', handler));
    // Remove listeners on cleanup
    return (): void =>
      mediaQueryLists.forEach((mql) =>
        mql.removeEventListener('change', handler),
      );
  }, [mediaQueryLists]);

  if (!Array.isArray(queries)) {
    return value[0];
  }

  return value;
}

export { useBreakpoint };
